import numpy as npimport matplotlib.pyplot as pltimport math as mathdef taylor_sin(x, order=7):    """    Approximate sin(x) using Taylor series expansion.    Parameters:        x (float or array): Input value(s) in radians.        order (int): Order of the Taylor series approximation.    Returns:        float or array: Approximated sin(x) value(s).    """    # Forcer x en tableau numpy pour éviter l’erreur d’attribut    x = np.array(x, dtype=float)    sin_x = x.copy()    for n in range(1, order // 2 + 1):        sin_x += ((-1)**n) * (x**(2*n + 1)) / math.factorial(2*n + 1)    return sin_xdef generate_dds_signal(f_out, fs, num_samples=1000, use_taylor=False, taylor_order=3, rom_reduction_factor=32):    """    DDS generation using:    - 16-bit phase accumulator    - Quarter-wave ROM (0 to π/2) to save 2 address bits    - Optional Taylor interpolation between LUT points    """    phase_accumulator = 0    phase_increment = int((f_out / fs) * 2**16)    accumulator_output = []    rom_output = []    # ==============================    # FULL ROM (reference)    # ==============================    rom_size = 2**16    rom_phase_values = np.linspace(0, 2*np.pi, rom_size, endpoint=False)    rom_sine_lut = np.round((np.sin(rom_phase_values) + 1) * (2**11 - 1)).astype(int)    # ==================================================    # QUARTER-WAVE ROM (0 → π/2) for reduced memory    # ==================================================    if use_taylor:        reduced_rom_size = (2**16 // rom_reduction_factor) // 4        reduced_rom_phase_values = np.linspace(0, np.pi/2, reduced_rom_size, endpoint=False)        reduced_rom_sine_lut = np.sin(reduced_rom_phase_values)    else:        reduced_rom_size = None        reduced_rom_sine_lut = None    for _ in range(num_samples):        accumulator_output.append(phase_accumulator)        if not use_taylor:            rom_output.append(rom_sine_lut[phase_accumulator])        else:            # Convert phase accumulator to real angle [0, 2π]            theta = (phase_accumulator / 2**16) * 2 * np.pi            # ==============================            # Determine quadrant            # ==============================            if 0 <= theta < np.pi/2:                theta_q = theta                sign = 1            elif np.pi/2 <= theta < np.pi:                theta_q = np.pi - theta                sign = 1            elif np.pi <= theta < 3*np.pi/2:                theta_q = theta - np.pi                sign = -1            else:                theta_q = 2*np.pi - theta                sign = -1            # ==============================            # Map to quarter-wave ROM index            # ==============================            rom_index = int((theta_q / (np.pi/2)) * (reduced_rom_size - 1))            theta0 = reduced_rom_phase_values[rom_index]            base_value = reduced_rom_sine_lut[rom_index]            # Small angle offset for Taylor interpolation            phase_offset = theta_q - theta0            # Taylor interpolation around theta0            approx = base_value + taylor_sin(phase_offset, taylor_order)            approximated_sine_value = sign * np.clip(approx, -1, 1)            rom_output.append(int(np.round((approximated_sine_value + 1) * (2**11 - 1))))        phase_accumulator = (phase_accumulator + phase_increment) % 2**16    return np.array(accumulator_output), np.array(rom_output), rom_sine_lut, reduced_rom_sine_lutdef dds_fft(rom_output, rom_output_taylor, taylor_order):    N_fft = len(rom_output)    # Conversion en pleine échelle [-1,1]    full_scale = 2**11 - 1    sig1 = (rom_output - np.mean(rom_output)) / full_scale    sig2 = (rom_output_taylor - np.mean(rom_output_taylor)) / full_scale    # Fenêtre pour éviter leakage    window = np.hanning(N_fft)    sig1 = sig1 * window    sig2 = sig2 * window    # FFT    fft1 = np.fft.fft(sig1)    fft2 = np.fft.fft(sig2)    mag1 = np.abs(fft1) / (np.sum(window)/2)    mag2 = np.abs(fft2) / (np.sum(window)/2)    # Conversion en dBFS    eps = 1e-12    mag1_db = 20 * np.log10(mag1 + eps)    mag2_db = 20 * np.log10(mag2 + eps)    # Recalage du pic fondamental à 0 dBFS    mag1_db -= np.max(mag1_db)    mag2_db -= np.max(mag2_db)    # Fréquence    fft_freq = np.fft.fftfreq(N_fft, 1/fs)    pos_freqs = fft_freq[:N_fft//2]    mag1_db = mag1_db[:N_fft//2]    mag2_db = mag2_db[:N_fft//2]    pink = (255 / 255, 105 / 255, 180 / 255)    # Plot    plt.figure(figsize=(12,5))    #plt.subplot(121)    plt.plot(pos_freqs, mag1_db, label="Full ROM", color=pink)    plt.title(f"Spectre DDS (dBFS) - {f_out/1e6} MHz")    plt.xlabel("Fréquence (Hz)")    plt.ylabel("Amplitude (dBFS)")    plt.xlim(0, 25e6)    plt.ylim(-80, 5)    plt.grid(True)    plt.figure(figsize=(12,5))    #plt.subplot(122)    plt.plot(pos_freqs, mag2_db, label="Taylor Approx : " + str(taylor_order), color=pink)    plt.title(f"Spectre DDS (dBFS) - {f_out/1e6} MHz")    plt.xlabel("Fréquence (Hz)")    plt.ylabel("Amplitude (dBFS)")    plt.xlim(0, 25e6)    plt.ylim(-80, 5)    plt.grid(True)    plt.legend()    plt.show()def add_awgn(signal, snr_db):    signal_power = np.mean(signal**2)    snr_linear = 10**(snr_db / 10)    noise_power = signal_power / snr_linear    noise = np.random.normal(0, np.sqrt(noise_power), len(signal))    return signal + noise# === Parameters ===f_out = 12.49e6  # Output frequency (12.5 MHz)fs = 50e6       # Sampling frequency (50 MHz)N = 4096         # Number of samplestaylor_order = 7rom_reduction_factor = 128# === Generate DDS signals ===accumulator_output, rom_output, _, _ = generate_dds_signal(f_out, fs, N)accumulator_output_taylor, rom_output_taylor, rom_sine_lut, reduced_rom_sine_lut = generate_dds_signal(f_out, fs, N, use_taylor=True, taylor_order=taylor_order, rom_reduction_factor=rom_reduction_factor)SNR_dB = 30  # Ajuste : 20 = très bruité, 40 = proprerom_output_noisy = add_awgn(rom_output, SNR_dB)rom_output_taylor_noisy = add_awgn(rom_output_taylor, SNR_dB)# === FFT Analysis ===dds_fft(rom_output_noisy, rom_output_taylor_noisy, taylor_order=taylor_order)#dds_fft(rom_output, rom_output_taylor, taylor_order=taylor_order)# === Plot DDS steps ===fig1, (ax1, ax2) = plt.subplots(2, 1, figsize=(8, 8))# Accumulator outputax1.plot(accumulator_output[:300], drawstyle='steps-post', color='blue')ax1.set_title('Accumulator Output (16-bit Sawtooth Waveform)')ax1.set_xlabel('Sample')ax1.set_ylabel('Phase Value')ax1.grid(True)# ROM outputax2.plot(rom_output[:300], drawstyle='steps-post', color='red', label='Full ROM')ax2.plot(rom_output_taylor[:300], drawstyle='steps-post', color='green', label='Taylor Approximation', linestyle="--")ax2.set_title('ROM Output (12-bit Quantized Sine Waveform)')ax2.set_xlabel('Sample')ax2.set_ylabel('Amplitude (12-bit)')ax2.grid(True)ax2.legend()# Full sinus over 0 → 2πplt.tight_layout()plt.show()